using System.Collections;
using NaughtyAttributes;
using Spine;
using Spine.Unity;
using UnityEngine;

namespace Astrea;

public class EventSpritesSkeleton : MonoBehaviour
{
	[SerializeField]
	protected SkeletonGraphic skeletonGraphic;

	[SerializeField]
	[HideIf("disableInitializePositioning")]
	private Vector2 defaultEventSpritesPosition;

	[SerializeField]
	private bool disableInitializePositioning;

	public SkeletonGraphic SkeletonGraphic => skeletonGraphic;

	public virtual void Initialize(ButtonCustomEventSetup buttonCustomEventSetup, SkeletonDataAsset skeletonDataAsset, string customStartingAnimationName, string afterStartingAnimationAnimationName)
	{
		skeletonGraphic.skeletonDataAsset = skeletonDataAsset;
		skeletonGraphic.Initialize(overwrite: true);
		if (afterStartingAnimationAnimationName != "")
		{
			StartCoroutine(AfterStartingAnimationCoroutine(customStartingAnimationName, afterStartingAnimationAnimationName));
		}
		else if (customStartingAnimationName != "")
		{
			skeletonGraphic.AnimationState.SetAnimation(0, customStartingAnimationName, loop: true);
		}
		if (!disableInitializePositioning)
		{
			if (buttonCustomEventSetup.EnableCustomEventSpritesPosition)
			{
				skeletonGraphic.rectTransform.localPosition = buttonCustomEventSetup.CustomEventSpritesPosition;
			}
			else
			{
				skeletonGraphic.rectTransform.localPosition = defaultEventSpritesPosition;
			}
		}
	}

	public IEnumerator AfterStartingAnimationCoroutine(string customStartingAnimationName, string afterStartingAnimationAnimationName)
	{
		TrackEntry trackEntry = skeletonGraphic.AnimationState.SetAnimation(0, customStartingAnimationName, loop: false);
		yield return new WaitForSpineAnimationComplete(trackEntry);
		skeletonGraphic.AnimationState.SetAnimation(0, afterStartingAnimationAnimationName, loop: true);
	}
}
